/* The sampled instruments' and drum hits' data (samples_data.c, generated by tools/samples/pack.py from
   tools/samples/manifest.json; sources and licenses in CREDITS.md). Read-only tables, no code that runs per sample.

   Format of every zone and hit: mono 4-bit IMA ADPCM (the standard step and index tables), two samples a byte, the
   earlier sample in the low nibble; `len` samples in (len + 1) / 2 bytes. Decoding starts from predictor 0 and step
   index `idx0` (the packer picks it per zone: a hit starts loud). A looped zone (loop_len > 0) is an attack then a
   crossfaded loop [loop_start, loop_start + loop_len): the decoder keeps its (predictor, index) as it first reaches
   loop_start and restores them at each wrap, which gives exactly the loop's samples again. `root` is the MIDI note the
   zone sounds when played at `rate` (the packer retunes each zone to a whole note; hits carry 60, played at `rate` for
   no shift). `gain` scales the decoded sample (as -1..1) to unit loudness: its RMS over the first 150 ms becomes 1.0,
   so a caller sets levels as loudness. */
#ifndef ENGINE_SAMPLES_H
#define ENGINE_SAMPLES_H
#include <stdint.h>

typedef struct { const uint8_t *data; uint32_t len, loop_start, loop_len; uint16_t rate; uint8_t root;
                 uint8_t idx0; float gain; } smp_zone_t;   /* ADPCM nibbles; loop_len 0 = one-shot; idx0 0..88 */
typedef struct { const smp_zone_t *z; uint8_t n; } smp_bank_t;  /* zones sorted by root */

/* Pitched banks: the Knight upright (VCSL), the FreePats Spanish classical nylon, the Karoryfer Emilyguitar, the
   VCSL vibraphone (soft mallets; the vibes lead). */
enum { SB_KNIGHT, SB_NYLON, SB_EMILY, SB_VIBES, SB_N };
/* Drum hits, one pool for every sampled kit, stored raw (a kit's pitch, low-pass and drive are applied at playback):
   GG Gogodze Phu Vol II (retro mic), BR Big Rusty, FS Frankensnare, VC VCSL. */
enum { SH_GG_KICK, SH_BR_KICK, SH_GG_SIDE, SH_GG_SNARE, SH_FS_POPLAR, SH_VC_ROPE, SH_GG_HAT, SH_GG_OHAT,
       SH_BR_CHICK, SH_BR_OHAT, SH_VC_PEDAL, SH_VC_HAT, SH_VC_OHAT, SH_VC_SHAKER, SH_RIDE, SH_N };

const smp_bank_t *smp_bank(int id);   /* NULL out of range */
const smp_zone_t *smp_hit(int id);    /* NULL out of range */
uint32_t smp_bytes(void);             /* total sample data, for mem-check and the test */

#endif
